<?php
use App\Libraries\{FormCatalog,GeographyCatalog};
$method=$method??'post';$target=$method==='get'?$base.'/'.$page:($personal?'/actions/'.$action:$base.'/actions/'.$action);
$safe=(array)session('safe_input');$useSafe=($safe['return_page']??$page)===$page && (!isset($hidden['ref'])||($safe['ref']??null)===$hidden['ref']);
$labels=['role'=>'Professional role','summary'=>$action==='profile'?'About your caregiving experience':($fields['summary'][0]??'Responsibilities'),'qualifications'=>'Qualifications and training','regions'=>'Where would you like to work?','region'=>'Work area','availability'=>'When are you available?','travel_radius'=>'How far can you travel?','languages'=>'Languages you speak','care_settings'=>'Where would you like to provide care?','proposed_seconds'=>'Corrected time worked','minutes'=>$action==='balance'?'Change leave balance':'Leave duration','employment_ref'=>$action==='clock'||$action==='leave'||$action==='expense'?'Your employment':'Employee','application_ref'=>'Candidate application','client_ref'=>'Client','starts_at'=>'Start date and time','ends_at'=>'End date and time','provider_ref'=>'Employee number in your payroll system','evidence_ref'=>'Supporting evidence reference'];
// Agency access roles retain their own labels instead of being confused with job titles.
if(!in_array($action,['profile','career','contract'],true))unset($labels['role']);
?>
<form <?= $method==='post'?'data-workflow':'' ?> data-form-action="<?= esc($action,'attr') ?>" method="<?= esc($method,'attr') ?>" action="<?= esc($target,'attr') ?>" class="<?= $inline?'inline-form':'form-grid' ?>">
<?php if($method==='post'): ?><?= csrf_field() ?>
<?php foreach(['workspace_nonce'=>$nonce,'return_page'=>$page]+$hidden as $key=>$value): ?><input type="hidden" name="<?= esc($key,'attr') ?>" value="<?= esc((string)$value,'attr') ?>"><?php endforeach;endif ?>
<?php foreach($fields as $original=>$spec):
    if(is_string($spec))$spec=[$spec];$key=ltrim($original,'?');$optional=str_starts_with($original,'?');
    $label=$labels[$key]??$spec[0];$type=$spec[1]??'text';$choices=$spec[2]??[];
    $value=$useSafe?($safe[$key]??($spec[3]??'')):($spec[3]??'');if(!is_scalar($value))$value='';$value=(string)$value;
    if($method==='get'){$value=service('request')->getGet($key)??$value;if(!is_scalar($value))$value='';$value=(string)$value;}
    $catalog=FormCatalog::choices($action,$key);if($catalog){[$type,$choices]=$catalog;}
    if(in_array($key,['regions','region'],true))$type='locations';
    if(in_array($key,['minutes','proposed_seconds'],true))$type='duration';
    if($type==='country'){$type='select';$choices=array_column(GeographyCatalog::countries(),'name','code');}
    $id=$action.'-'.$key.'-'.bin2hex(random_bytes(3));$helpId=$id.'-hint';[$explain,$example]=FormCatalog::help($action,$key,$label);
    $required=$optional?'':' required';$wide=in_array($type,['textarea','tags','locations'],true);
    $helpButton='<button type="button" class="field-help" aria-label="Help with '.esc($label,'attr').'" aria-haspopup="dialog" data-help-title="'.esc($label,'attr').'" data-help-text="'.esc($explain,'attr').'" data-help-example="'.esc($example,'attr').'">?</button>';
    if($type==='checkbox'): ?><div class="consent-field"><label class="check"><input name="<?= esc($key,'attr') ?>" type="checkbox" value="yes"<?= $required ?>><?= esc($label) ?></label><?= $helpButton ?></div><?php continue;endif ?>
<div class="field<?= $wide?' wide':'' ?>" data-field="<?= esc($key,'attr') ?>">
<div class="field-label"><label for="<?= $id ?>"><?= esc($label) ?><?php if($action==='agency'&&!$optional): ?><span class="required-mark" aria-hidden="true"> *</span><?php endif ?><?php if($optional): ?><span class="optional-label">Optional</span><?php endif ?></label><?= $helpButton ?></div>
<?php if($type==='select'): ?>
<select id="<?= $id ?>" name="<?= esc($key,'attr') ?>"<?= $required ?>><option value="">Choose an option…</option><?php if($value!==''&&!array_key_exists($value,$choices)): ?><option value="<?= esc($value,'attr') ?>" selected><?= esc($value) ?></option><?php endif;foreach($choices as $k=>$v): ?><option value="<?= esc((string)$k,'attr') ?>"<?= $value===(string)$k?' selected':'' ?>><?= esc((string)$v) ?></option><?php endforeach ?></select>
<?php elseif($type==='choice'): ?>
<div data-choice><input id="<?= $id ?>" name="<?= esc($key,'attr') ?>" value="<?= esc($value,'attr') ?>" maxlength="<?= $key==='role'?100:160 ?>" data-choice-value<?= $required ?>><select data-choice-select hidden aria-label="<?= esc($label,'attr') ?>"><option value="">Choose an option…</option><?php foreach($choices as $choice): ?><option value="<?= esc($choice,'attr') ?>"><?= esc($choice) ?></option><?php endforeach ?><option value="__other__">Other — enter your own</option></select><input type="text" data-choice-other hidden maxlength="<?= $key==='role'?100:160 ?>" placeholder="Enter your own <?= esc(mb_strtolower($label),'attr') ?>" aria-label="Other <?= esc($label,'attr') ?>"></div>
<?php elseif($type==='tags'): ?>
<div data-tag-picker data-label="<?= esc($label,'attr') ?>" data-options="<?= esc(json_encode($choices,JSON_UNESCAPED_UNICODE),'attr') ?>"><input id="<?= $id ?>" name="<?= esc($key,'attr') ?>" value="<?= esc($value,'attr') ?>" maxlength="<?= $key==='availability'?200:500 ?>" data-tag-value<?= $required ?>><div data-tag-ui hidden><div class="selected-tags" data-selected-tags aria-live="polite"></div><label class="sr-only" for="<?= $id ?>-search">Search <?= esc($label) ?></label><input id="<?= $id ?>-search" type="search" data-tag-search placeholder="Search available <?= esc(mb_strtolower($label),'attr') ?>…" autocomplete="off"><div class="tag-options" data-tag-options></div><div class="custom-entry"><label class="sr-only" for="<?= $id ?>-other">Add another <?= esc(mb_strtolower($label)) ?></label><input id="<?= $id ?>-other" data-tag-custom placeholder="Not listed? Type your own…" maxlength="120"><button type="button" class="secondary" data-tag-add>Add</button></div><p class="field-hint" data-tag-message role="status">Select as many as you need. You can also add your own.</p></div></div>
<?php elseif($type==='locations'):
    $initial=[];foreach(array_filter(array_map('trim',explode(',',$value))) as $code){$r=GeographyCatalog::resolve($code);$initial[]=$r??['code'=>$code,'label'=>'Previously saved work area'];}
?>
<div data-location-picker data-multiple="<?= $key==='regions'?'true':'false' ?>" data-initial="<?= esc(json_encode($initial,JSON_UNESCAPED_UNICODE),'attr') ?>"><input id="<?= $id ?>" name="<?= esc($key,'attr') ?>" value="<?= esc($value,'attr') ?>" data-location-value<?= $required ?>><div data-location-ui hidden><div class="location-grid"><div><div class="geo-label"><label for="<?= $id ?>-country">Country</label><button type="button" class="field-help" aria-label="Help with country" aria-haspopup="dialog" data-help-title="Country" data-help-text="Choose the country where you would like to work. The next lists will show locations in that country." data-help-example="United States or Fiji">?</button></div><select id="<?= $id ?>-country" data-geo-country><option value="">Choose a country…</option><?php foreach(GeographyCatalog::countries() as $country): ?><option value="<?= esc($country['code'],'attr') ?>"><?= esc($country['name']) ?></option><?php endforeach ?></select></div><div><div class="geo-label"><label for="<?= $id ?>-state">State or province</label><button type="button" class="field-help" aria-label="Help with state or province" aria-haspopup="dialog" data-help-title="State or province" data-help-text="After choosing a country, choose its state, province or main administrative area. You may also select the entire country." data-help-example="California in the United States">?</button></div><select id="<?= $id ?>-state" data-geo-state disabled><option value="">Choose a country first</option></select></div><div><div class="geo-label"><label for="<?= $id ?>-county">County or district <span class="optional-label">Optional</span></label><button type="button" class="field-help" aria-label="Help with county or district" aria-haspopup="dialog" data-help-title="County or district" data-help-text="Optionally narrow the state or province to a county or district. Leave this blank to include a broader work area. Some countries use a different administrative structure." data-help-example="Sacramento County in California">?</button></div><select id="<?= $id ?>-county" data-geo-county disabled><option value="">Choose a state first</option></select></div><div><div class="geo-label"><label for="<?= $id ?>-city">City or town <span class="optional-label">Optional</span></label><button type="button" class="field-help" aria-label="Help with city or town" aria-haspopup="dialog" data-help-title="City or town" data-help-text="Choose a particular city or town, or leave it blank to use the whole selected county, state or country. Some very small places may not be listed." data-help-example="Davis in Yolo County, California">?</button></div><select id="<?= $id ?>-city" data-geo-city disabled><option value="">Choose a state first</option></select></div></div><button type="button" class="secondary add-area" data-geo-add><?= $key==='regions'?'Add work area':'Use this work area' ?></button><div class="selected-tags location-tags" data-geo-selected aria-live="polite"></div><p class="field-hint" data-geo-message role="status">Select an entire state or narrow your choice to a county or city. Location codes are saved automatically.</p><p class="field-hint">Place names: <a href="https://www.geonames.org/" target="_blank" rel="noopener">GeoNames</a>, CC BY 4.0. Some small places or administrative divisions may not be listed.</p></div></div>
<?php elseif($type==='duration'): $factor=$key==='proposed_seconds'?3600:60; ?>
<div data-duration data-base="<?= $key==='proposed_seconds'?'seconds':'minutes' ?>"><input id="<?= $id ?>" name="<?= esc($key,'attr') ?>" value="<?= esc($value,'attr') ?>" data-duration-value<?= $required ?>><div class="duration-controls" data-duration-ui hidden><input type="number" data-duration-amount aria-label="<?= esc($label,'attr') ?> amount" step="any"<?= $action!=='balance'?' min="0"':'' ?> value="<?= $value!==''?esc((string)((float)$value/$factor),'attr'):'' ?>"><select data-duration-unit aria-label="Duration unit"><option value="hours">Hours</option><option value="minutes">Minutes</option><?php if($key==='proposed_seconds'): ?><option value="seconds">Seconds</option><?php endif ?></select></div></div>
<?php elseif($type==='textarea'): ?><textarea id="<?= $id ?>" name="<?= esc($key,'attr') ?>" maxlength="<?= $key==='summary'?3000:12000 ?>" placeholder="<?= esc($example,'attr') ?>"<?= $required ?>><?= esc($value) ?></textarea>
<?php else: ?><input id="<?= $id ?>" name="<?= esc($key,'attr') ?>" type="<?= esc($type,'attr') ?>" value="<?= esc($type==='password'?'':$value,'attr') ?>"<?= $type==='password'?' autocomplete="current-password"':'' ?><?= !in_array($type,['password','date','datetime-local','number'],true)?' placeholder="'.esc($example,'attr').'"':'' ?><?= $required ?>><?php endif ?>
</div>
<?php endforeach ?>
<?php if($action==='agency'){echo view('components/agency_phones',['safe'=>$safe]);echo view('components/agency_address',['safe'=>$safe]);} ?>
<div class="buttons"><button type="submit"><?= esc($button) ?></button></div></form>
